#include "os.h"
#include "isr.h"
#include "sys_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

void sys_os_timer_irq (void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sys_init_os_timer (void)
{
  isr_set_vector (ISR_ID_SYS_TICK , ISR_PRI_31 , ISR_TYPE_IRQ , sys_irq_timer_service) ;

  SysTick->LOAD = (CPU_CLOCK_HZ/1000) - 1 ; // 1 ms @ cpu clock 
  SysTick->CTRL = 0x00000007 ; // Counter enabled, irq enabled, clock=cpu 
}

